import{_ as a,o as r,c as d,a2 as e}from"./chunks/framework.BWuWLRhz.js";const c=JSON.parse('{"title":"家长端小程序","description":"AgoraIn 家长端微信小程序 —— 通知、成绩、值日与留言","frontmatter":{"title":"家长端小程序","description":"AgoraIn 家长端微信小程序 —— 通知、成绩、值日与留言"},"headers":[],"relativePath":"miniprogram/index.md","filePath":"miniprogram/index.md","lastUpdated":1791175900000}'),o={name:"miniprogram/index.md"};function i(n,t,l,h,s,p){return r(),d("div",null,[...t[0]||(t[0]=[e('<h1 id="家长端小程序" tabindex="-1">家长端小程序 <a class="header-anchor" href="#家长端小程序" aria-label="Permalink to &quot;家长端小程序&quot;">​</a></h1><p>家长端小程序与移动端 App <strong>功能对等</strong>，是家长了解孩子在校情况、与老师沟通的统一入口。</p><h2 id="能做什么" tabindex="-1">能做什么 <a class="header-anchor" href="#能做什么" aria-label="Permalink to &quot;能做什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模块</th><th>说明</th></tr></thead><tbody><tr><td>通知与已读回执</td><td>学校 / 班级通知实时送达；已读状态回传给教师，谁没看到一目了然</td></tr><tr><td>成绩概览</td><td>受学校隐私开关控制（<strong>默认关闭</strong>），开启后可见成绩与排名区间</td></tr><tr><td>考勤与积分</td><td>查看孩子签到、请假与积分变动</td></tr><tr><td>值日安排</td><td>今日值日、本周轮换</td></tr><tr><td>班级资源</td><td>教师下发的资料在线查看与下载</td></tr><tr><td>留言沟通</td><td>直接给老师留言，沟通留痕，不再依赖家长群刷屏</td></tr><tr><td>多孩切换</td><td>一个账号可绑定多个孩子，随时切换</td></tr></tbody></table><h2 id="与-app-的关系" tabindex="-1">与 App 的关系 <a class="header-anchor" href="#与-app-的关系" aria-label="Permalink to &quot;与 App 的关系&quot;">​</a></h2><table tabindex="0"><thead><tr><th>端</th><th>形态</th><th>覆盖能力</th></tr></thead><tbody><tr><td>微信小程序</td><td>免安装，微信内直接使用</td><td>家长全部功能</td></tr><tr><td>移动端 App</td><td>Android</td><td>家长中心 + 学生扫码签到 + 教师拍照扫卡与逐题改分</td></tr></tbody></table><blockquote><p>家长端采用<strong>邀请码绑定</strong>：教师在后台按班级批量生成 6 位邀请码（可导出 CSV 打印发放）， 家长输入即完成绑定，无需邮箱验证码。</p></blockquote><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/miniprogram/features.html">功能特性</a></li><li><a href="/miniprogram/quickstart.html">快速开始（家长绑定）</a></li><li><a href="/miniprogram/structure.html">目录结构</a>：开发者视角的工程说明</li></ul>',9)])])}const u=a(o,[["render",i]]);export{c as __pageData,u as default};
